RECIPE_SHA='edb7d43ab7950f4530b00562c3d00d1d32d269c79a57d68e5d75e77f7d9f59c8'
def blob(b):return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()
def main():
 if os.environ.get('GITHUB_REF')!='refs/heads/chatgpt/1261-release-validation-20261030':raise SystemExit('Validation branch only')
 if hashlib.sha256(RECIPE.encode()).hexdigest()!=RECIPE_SHA:raise SystemExit('Recipe drift')
 receipt=ROOT/'docs/LICENSING_WORKSPACE_SOURCE.json'
 if receipt.exists():
  if json.loads(receipt.read_text()).get('recipe_sha256')!=RECIPE_SHA:raise SystemExit('Unexpected receipt')
  print('Licensing workspace source already recorded');return
 outputs=[];evidence=[]
 for item in json.loads(RECIPE):
  path=ROOT/item['path']
  if not item['path'].startswith(('site/','tests/')) or '..' in Path(item['path']).parts or path.is_symlink() or any(p.is_symlink() for p in path.parents):raise SystemExit('Unsafe path')
  raw=path.read_bytes()
  if blob(raw)!=item['before']:raise SystemExit('Source drift: '+item['path'])
  text=raw.decode()
  for start,end,new in reversed(item['edits']):text=text[:start]+new+text[end:]
  out=text.encode()
  if blob(out)!=item['after']:raise SystemExit('Output drift: '+item['path'])
  outputs.append((path,out));evidence.append({k:item[k] for k in ['path','before','after']})
 for path,out in outputs:path.write_bytes(out)
 receipt.write_text(json.dumps({'schema':1,'recipe_sha256':RECIPE_SHA,'files':evidence,'status':'Connected source; exact-source SQL/browser acceptance required'},indent=2)+'\n')
 subprocess.run(['git','diff','--check'],cwd=ROOT,check=True)
if __name__=='__main__':main()
